import csv
cols=["row_id","class","population","context","factor","reported_value","proposed_distribution","basis","source","url","notes"]
R=[]
def r(**k): R.append(k)
RB="(user PDF) Rankin & Barlow 2007"; CA="(user PDF) Calderan et al. 2014"; ES="https://os.copernicus.org/articles/15/75/2019/os-15-75-2019.pdf"
