S="Sei"
r(**{"class":S},population="all",context="all",factor="Context balance",reported_value="downsweep calling (singles/pairs/triplets), upsweep sets, mixed upsweep-downsweep; little behavioural context reported",proposed_distribution="EQUAL encounters per call-pattern context: downsweep doublets/triplets, upsweep sets, mixed",basis="design rule",source="-",url="")
r(**{"class":S},population="Hawaii",context="Downsweeps",factor="Group size / calls per encounter",reported_value="sonobuoy within 100 m of a group of 3; 2 h near group; 107 calls (105 low downsweeps + 2 high); 5 groups sighted over 3 days; individual callers not distinguishable",proposed_distribution="group 1-4 animals, 1-2 callers; ~50 calls/h during active calling (derived)",basis="literature (derived rate)",source="Rankin & Barlow 2007",url=RB)
r(**{"class":S},population="Southern Ocean S of NZ",context="Upsweep sets / mixed",factor="Calls per encounter, sets",reported_value="38 calls in 1 h 40 min from 2 sightings ~11 km apart (~23 calls/h); upsweeps in sets of 2-9 (ICI 10.3+-2.3 s); upsweep-downsweep set of 4 (ICI 4.8 s); first calls faint",proposed_distribution="sets of 2-9 calls; ~10-40 calls/h; sets separated by silences lognormal median 5 min (assumed)",basis="literature + assumed silence",source="Calderan et al. 2014",url=CA)
r(**{"class":S},population="Chilean Patagonia",context="Downsweeps",factor="Grouping",reported_value="pairs 12, singles 5, triplets 4 (of 21 groupings); 41 calls over 2 years of sightings",proposed_distribution="grouping: pair 0.57, single 0.24, triplet 0.19; doublet INI ~4 s",basis="literature",source="Espanol-Jimenez et al. 2019",url=ES)
r(**{"class":S},population="Juan Fernandez",context="Downsweeps / upsweeps",factor="Interval structure and between-year switching",reported_value="downsweep INI 4 s in all 3 years; upsweep INI 7 s (2015-16) or 14 s (2017)",proposed_distribution="upsweep INI mode drawn per encounter (7 or 14 s); downsweep INI ~4 s",basis="literature",source="Alvarez Abarzua et al. 2024",url=AA)
r(**{"class":S},population="all (Atlantic tag data)",context="all",factor="Overall call rate and silence",reported_value="12 tags, ~173 h, 1030 calls -> ~3 calls/h overall (higher at twilight); calls at <10 m depth",proposed_distribution="encounter-average rate lognormal median 5/h (1-50): long silences between active calling spells (active spells ~20-50 calls/h)",basis="literature (Atlantic, flagged) + Pacific derived active rates",source="Cusano et al. 2023 JASA 154:3543 (Atlantic)",url=CU,notes="behavioural prior only; Atlantic call types not used")
r(**{"class":S},population="all",context="all",factor="Individual vs population",reported_value="not reported",proposed_distribution="within-caller SD 0.3 x population SD (assumed)",basis="assumed",source="-",url="")
r(**{"class":S},population="all",context="all",factor="Range / detectability",reported_value="faint first calls at range (Calderan); upsweep high-frequency end attenuates with distance",proposed_distribution="range log-uniform 0.5-50 km -> completeness/fragmentation; upper part of upsweeps lost first",basis="literature + assumed",source="Calderan et al. 2014",url=CA)
r(**{"class":S},population="all",context="Chorus",factor="Chorus",reported_value="none reported",proposed_distribution="no chorus layer",basis="literature (absence)",source="-",url="")
G="Gray"
BU="https://www.frontiersin.org/articles/10.3389/fmars.2018.00329/pdf"; CL="(user PDF) Crane & Lashkari 1996"; DA="(user PDF) Dahlheim 1987"; GZ="https://repository.library.noaa.gov/view/noaa/24877/noaa_24877_DS1.pdf"
r(**{"class":G},population="Eastern N Pacific",context="all",factor="Context balance",reported_value="migration (moans dominate), breeding lagoon (tonal S3/S4/S2 in v1), Arctic feeding (N3/N4)",proposed_distribution="EQUAL encounters per context: southbound migration, northbound migration, lagoon, Arctic feeding",basis="design rule",source="-",url="",notes="knocks excluded in v1")
r(**{"class":G},population="Migration (California)",context="Migration",factor="Calls per track / ICI",reported_value="280 tracks: mean 8.4 calls per track (max 32; tracks needed >=5 calls); ICI within tracks 3.89+-2.31 min; implied track ~30 min; one focal caller per track",proposed_distribution="calling spell: 5-32 moans, ICI ~ N(3.9, 2.3) min (>0.3); 1 caller (p 0.8) or 2",basis="literature",source="Guazzo et al. 2017 PLoS ONE",url=GZ)
r(**{"class":G},population="Migration",context="Migration",factor="Population-average rate and silent whales",reported_value="5.7 calls/whale/day (0.24/h) on average; rates highly variable; tracked whales call much more; ~1/3 of solitary migrants made detectable sounds (Cummings); Crane: 0.05 calls/h/whale; 258 sounds in 69.8 h (~3.7/h overall: shallow ~4.3/h, deep ~2.0/h, derived); often silent over deep water",proposed_distribution="each animal vocal with p = 0.33; vocal animals produce calling spells (above) separated by silences lognormal median 1 h (0.2-6 h); deep-water encounters get longer silences",basis="literature",source="Guazzo 2017; Crane & Lashkari 1996; Cummings et al. (cited)",url=GZ)
r(**{"class":G},population="Migration",context="Migration",factor="Diel and direction",reported_value=">2x more calls at night; 197 of 280 tracks at night; southbound dominates until mid-Feb; moans 84% (N) vs 98% (S) of calls at Vancouver Is.",proposed_distribution="diel state per encounter (night: x2 rate); direction sets call mix (northbound adds upsweeps/downsweeps/grunts)",basis="literature",source="Guazzo 2017; Burnham et al. 2018",url=BU)
r(**{"class":G},population="Migration",context="Migration",factor="Group size / movement",reported_value="groups 1-7, mostly 1-3; swim 1.6+-0.59 m/s; 1.7-3.4 km offshore",proposed_distribution="group 1-3 (weights 0.5, 0.3, 0.2), occasionally up to 7; caller passes recorder at ~1.6 m/s -> range changes quickly (detectability rises then falls over ~30-60 min)",basis="literature",source="Crane & Lashkari 1996; Guazzo 2017",url=GZ)
r(**{"class":G},population="Breeding lagoon (San Ignacio)",context="Lagoon",factor="Call rate",reported_value="Feb 84 sounds/h (62-128) with ~258 whales; Mar 50/h (38-86) with ~195 whales (0.33 and 0.25 sounds/h/whale); 83% of lagoon sounds were knocks (M1/S1); S3 moans 1%, S4 5%, S2 5%",proposed_distribution="lagoon encounters: many whales, tonal calls (S2/S3/S4) only ~11% of sounds -> tonal rate ~5-15/h, irregular; no song",basis="literature",source="Dahlheim 1987; Crane & Lashkari 1996",url=DA,notes="v1 lagoon encounters will be sparse because knocks are excluded")
r(**{"class":G},population="Breeding lagoon",context="Lagoon",factor="Calling-rate variability between sessions",reported_value="control 18.6 sounds per 15 min; up to 23.9-45.5+-11 per 15 min when disturbed/playbacks",proposed_distribution="per-encounter lagoon rate scale lognormal (CV ~0.4)",basis="literature",source="Dahlheim 1987",url=DA)
r(**{"class":G},population="Arctic feeding (Bering/Chukchi)",context="Feeding",factor="Call activity",reported_value="N3 moans and N4 grunts reported with low received levels (~65 dB, near ambient); no rates in our sources",proposed_distribution="rate lognormal median 5/h (1-30) (assumed); poor detectability (more fragmentation)",basis="assumed",source="Moore & Ljungblad 1984 via Dahlheim 1987",url=DA)
r(**{"class":G},population="all",context="all",factor="Individual vs population",reported_value="not reported",proposed_distribution="within-caller SD 0.3 x population SD (assumed)",basis="assumed",source="-",url="")
r(**{"class":G},population="all",context="all",factor="Range / detectability",reported_value="sounds 5-20 dB above ambient (Dahlheim); poor SNR along migration; M3 energy partly below 40 Hz",proposed_distribution="range log-uniform 0.2-10 km -> mostly low-to-moderate detectability; heavy fragmentation common",basis="literature + assumed",source="Crane & Lashkari 1996; Dahlheim 1987",url=CL)
r(**{"class":G},population="all",context="Chorus",factor="Chorus",reported_value="none reported (lagoon has many simultaneous callers, mostly knocks)",proposed_distribution="lagoon: 2-10 simultaneous tonal callers at varied ranges; no chorus layer elsewhere",basis="literature + assumed",source="Dahlheim 1987",url=DA)
for prefix,cls in (("SEX","Sei"),("GWX","Gray")):
    rows=[x for x in R if x["class"]==cls]
    for i,x in enumerate(rows,1): x["row_id"]=f"{prefix}{i:02d}"
    fn=f"encounter_context_{cls.lower()}.csv"
    with open(fn,"w",newline="",encoding="utf-8") as f:
        w=csv.DictWriter(f,fieldnames=cols); w.writeheader(); [w.writerow({c:x.get(c,"") for c in cols}) for x in rows]
    print(fn,len(rows))
